package local.ondemand;
import org.json.*;import java.util.*;import java.time.*;
final class EpisodeInfo {
 static long release(JSONObject v){String date=v.optString("released",v.optString("releaseDate","")).trim();if(date.isEmpty())return 0;try{return Instant.parse(date).toEpochMilli();}catch(Exception ignored){}try{return OffsetDateTime.parse(date).toInstant().toEpochMilli();}catch(Exception ignored){}try{return LocalDate.parse(date.substring(0,10)).atStartOfDay(ZoneOffset.UTC).toInstant().toEpochMilli();}catch(Exception ignored){return 0;}}
 static boolean upcoming(JSONObject v){return release(v)>System.currentTimeMillis();}
 static boolean listed(JSONObject v){return v!=null&&!v.optString("id").isEmpty()&&v.optInt("season",-1)>=0&&v.optInt("episode",0)>0;}
 static List<JSONObject> episodes(JSONObject full,int season){List<JSONObject> out=new ArrayList<>();JSONArray videos=full.optJSONArray("videos");if(videos!=null)for(int i=0;i<videos.length();i++){JSONObject v=videos.optJSONObject(i);if(listed(v)&&v.optInt("season")==season)out.add(v);}Collections.sort(out,(x,y)->Integer.compare(x.optInt("episode"),y.optInt("episode")));return out;}
 static SortedSet<Integer> seasons(JSONObject full){SortedSet<Integer> out=new TreeSet<>();JSONArray videos=full.optJSONArray("videos");if(videos!=null)for(int i=0;i<videos.length();i++){JSONObject v=videos.optJSONObject(i);if(listed(v))out.add(v.optInt("season"));}return out;}
 static String date(JSONObject v){String source=v.optString("released",v.optString("releaseDate","")).trim();try{return LocalDate.parse(source.substring(0,10)).format(java.time.format.DateTimeFormatter.ofPattern("MMM d, yyyy",Locale.getDefault()));}catch(Exception ignored){return "Release date to be announced";}}
 static String label(int season){return season==0?"Specials":"Season "+season;}
 static JSONObject next(JSONObject full,String current){JSONObject active=null;JSONArray videos=full.optJSONArray("videos");if(videos==null)return null;for(int i=0;i<videos.length();i++){JSONObject v=videos.optJSONObject(i);if(listed(v)&&current.equals(v.optString("id")))active=v;}if(active==null)return null;int season=active.optInt("season"),episode=active.optInt("episode");JSONObject best=null;for(int i=0;i<videos.length();i++){JSONObject v=videos.optJSONObject(i);if(!listed(v))continue;int s=v.optInt("season"),e=v.optInt("episode");if(s<season||s==season&&e<=episode)continue;if(best==null||s<best.optInt("season")||s==best.optInt("season")&&e<best.optInt("episode"))best=v;}return best!=null&&!upcoming(best)?best:null;}
 static String highResolution(String url){try{java.net.URI u=new java.net.URI(url);if("episodes.metahub.space".equals(u.getHost()))return url.replaceFirst("/w[0-9]+\\.jpg$","/original.jpg");if("image.tmdb.org".equals(u.getHost()))return url.replaceFirst("/t/p/w[0-9]+/","/t/p/original/");}catch(Exception ignored){}return url;}
 static String image(JSONObject v,JSONObject full){for(String k:new String[]{"thumbnail","image","screenshot"}){String url=v.optString(k);if(url.startsWith("https://"))return url;}return full.optString("background",full.optString("poster"));}
}
